    95  /**
    96   * Do different actions on the CURL handle for different received TLVs.
    97   */
    98  int fuzz_parse_tlv(FUZZ_DATA *fuzz, TLV *tlv)
    99  {
   100    int rc;
   101    char *tmp = NULL;
   102    uint32_t tmp_u32;
   103
   104    switch(tlv->type) {
   105      /* The pointers in response TLVs will always be valid as long as the fuzz
   106         data is in scope, which is the entirety of this file. */
   107      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE0, 0);
   108      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE1, 1);
   109      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE2, 2);
   110      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE3, 3);
   111      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE4, 4);
   112      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE5, 5);
   113      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE6, 6);
   114      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE7, 7);
   115      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE8, 8);
   116      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE9, 9);
   117      FRESPONSETLV(&fuzz->sockman[0], TLV_TYPE_RESPONSE10, 10);
   118
   119      FRESPONSETLV(&fuzz->sockman[1], TLV_TYPE_SECOND_RESPONSE0, 0);
   120      FRESPONSETLV(&fuzz->sockman[1], TLV_TYPE_SECOND_RESPONSE1, 1);
   121
   122      case TLV_TYPE_UPLOAD1:
   123        /* The pointers in the TLV will always be valid as long as the fuzz data
   124           is in scope, which is the entirety of this file. */
   125
   126        FCHECK_OPTION_UNSET(fuzz, CURLOPT_UPLOAD);
   127
   128        fuzz->upload1_data = tlv->value;
   129        fuzz->upload1_data_len = tlv->length;
   130
   131        FSET_OPTION(fuzz, CURLOPT_UPLOAD, 1L);
   132        FSET_OPTION(fuzz,
   133                    CURLOPT_INFILESIZE_LARGE,
   134                    (curl_off_t)fuzz->upload1_data_len);
   135        break;
   136
   137      case TLV_TYPE_HEADER:
   138        /* Limit the number of headers that can be added to a message to prevent
   139           timeouts. */
   140        if(fuzz->header_list_count >= TLV_MAX_NUM_CURLOPT_HEADER) {
   141          rc = 255;
   142          goto EXIT_LABEL;
   143        }
   144
   145        tmp = fuzz_tlv_to_string(tlv);
   146        fuzz->header_list = curl_slist_append(fuzz->header_list, tmp);
   147        fuzz->header_list_count++;
   148        break;
   149
   150      case TLV_TYPE_MAIL_RECIPIENT:
   151        tmp = fuzz_tlv_to_string(tlv);
   152        fuzz->mail_recipients_list =
   153                              curl_slist_append(fuzz->mail_recipients_list, tmp);
   154        break;
   155
   156      case TLV_TYPE_MIME_PART:
   157        if(fuzz->mime == NULL) {
   158          fuzz->mime = curl_mime_init(fuzz->easy);
   159        }
   160
   161        fuzz->part = curl_mime_addpart(fuzz->mime);
   162
   163        /* This TLV may have sub TLVs. */
   164        fuzz_add_mime_part(tlv, fuzz->part);
   165        break;
   166
   167      case TLV_TYPE_POSTFIELDS:
   168        FCHECK_OPTION_UNSET(fuzz, CURLOPT_POSTFIELDS);
   169        fuzz->postfields = fuzz_tlv_to_string(tlv);
   170        FSET_OPTION(fuzz, CURLOPT_POSTFIELDS, fuzz->postfields);
   171        break;
   172
   173      /* Define a set of u32 options. */
   174      FU32TLV(fuzz, TLV_TYPE_HTTPAUTH, CURLOPT_HTTPAUTH);
   175      FU32TLV(fuzz, TLV_TYPE_OPTHEADER, CURLOPT_HEADER);
   176      FU32TLV(fuzz, TLV_TYPE_NOBODY, CURLOPT_NOBODY);
   177      FU32TLV(fuzz, TLV_TYPE_FOLLOWLOCATION, CURLOPT_FOLLOWLOCATION);
   178      FU32TLV(fuzz, TLV_TYPE_WILDCARDMATCH, CURLOPT_WILDCARDMATCH);
   179      FU32TLV(fuzz, TLV_TYPE_RTSP_REQUEST, CURLOPT_RTSP_REQUEST);
   180      FU32TLV(fuzz, TLV_TYPE_RTSP_CLIENT_CSEQ, CURLOPT_RTSP_CLIENT_CSEQ);
   181      FU32TLV(fuzz, TLV_TYPE_HTTP_VERSION, CURLOPT_HTTP_VERSION);
   182
   183      /* Define a set of singleton TLVs - they can only have their value set once
   184         and all follow the same pattern. */
   185      FSINGLETONTLV(fuzz, TLV_TYPE_URL, CURLOPT_URL);
   186      FSINGLETONTLV(fuzz, TLV_TYPE_DOH_URL, CURLOPT_DOH_URL);
   187      FSINGLETONTLV(fuzz, TLV_TYPE_USERNAME, CURLOPT_USERNAME);
   188      FSINGLETONTLV(fuzz, TLV_TYPE_PASSWORD, CURLOPT_PASSWORD);
   189      FSINGLETONTLV(fuzz, TLV_TYPE_COOKIE, CURLOPT_COOKIE);
   190      FSINGLETONTLV(fuzz, TLV_TYPE_RANGE, CURLOPT_RANGE);
   191      FSINGLETONTLV(fuzz, TLV_TYPE_CUSTOMREQUEST, CURLOPT_CUSTOMREQUEST);
   192      FSINGLETONTLV(fuzz, TLV_TYPE_MAIL_FROM, CURLOPT_MAIL_FROM);
   193      FSINGLETONTLV(fuzz, TLV_TYPE_ACCEPTENCODING, CURLOPT_ACCEPT_ENCODING);
   194      FSINGLETONTLV(fuzz, TLV_TYPE_RTSP_SESSION_ID, CURLOPT_RTSP_SESSION_ID);
   195      FSINGLETONTLV(fuzz, TLV_TYPE_RTSP_STREAM_URI, CURLOPT_RTSP_STREAM_URI);
   196      FSINGLETONTLV(fuzz, TLV_TYPE_RTSP_TRANSPORT, CURLOPT_RTSP_TRANSPORT);
   197      FSINGLETONTLV(fuzz, TLV_TYPE_MAIL_AUTH, CURLOPT_MAIL_AUTH);
   198
   199      default:
   200        /* The fuzzer generates lots of unknown TLVs - we don't want these in the
   201           corpus so we reject any unknown TLVs. */
   202        rc = 127;
   203        goto EXIT_LABEL;
   204        break;
   205    }
   206
   207    rc = 0;
   208
   209  EXIT_LABEL:
   210
   211    fuzz_free((void **)&tmp);
   212
   213    return rc;
   214  }
