   216  /**
   217   * Converts a TLV data and length into an allocated string.
   218   */
   219  char *fuzz_tlv_to_string(TLV *tlv)
   220  {
   221    char *tlvstr;
   222
   223    /* Allocate enough space, plus a null terminator */
   224    tlvstr = (char *)malloc(tlv->length + 1);
   225
   226    if(tlvstr != NULL) {
   227      memcpy(tlvstr, tlv->value, tlv->length);
   228      tlvstr[tlv->length] = 0;
   229    }
   230
   231    return tlvstr;
   232  }
