   234  /**
   235   * Extract the values from the TLV.
   236   */
   237  int fuzz_add_mime_part(TLV *src_tlv, curl_mimepart *part)
   238  {
   239    FUZZ_DATA part_fuzz;
   240    TLV tlv;
   241    int rc = 0;
   242    int tlv_rc;
   243
   244    memset(&part_fuzz, 0, sizeof(FUZZ_DATA));
   245
   246    if(src_tlv->length < sizeof(TLV_RAW)) {
   247      /* Not enough data for a single TLV - don't continue */
   248      goto EXIT_LABEL;
   249    }
   250
   251    /* Set up the state parser */
   252    part_fuzz.state.data = src_tlv->value;
   253    part_fuzz.state.data_len = src_tlv->length;
   254
   255    for(tlv_rc = fuzz_get_first_tlv(&part_fuzz, &tlv);
   256        tlv_rc == 0;
   257        tlv_rc = fuzz_get_next_tlv(&part_fuzz, &tlv)) {
   258
   259      /* Have the TLV in hand. Parse the TLV. */
   260      rc = fuzz_parse_mime_tlv(part, &tlv);
   261
   262      if(rc != 0) {
   263        /* Failed to parse the TLV. Can't continue. */
   264        goto EXIT_LABEL;
   265      }
   266    }
   267
   268    if(tlv_rc != TLV_RC_NO_MORE_TLVS) {
   269      /* A TLV call failed. Can't continue. */
   270      goto EXIT_LABEL;
   271    }
   272
   273  EXIT_LABEL:
   274
   275    return(rc);
   276  }
   277
   278  /**
   279   * Do different actions on the mime part for different received TLVs.
   280   */
   281  int fuzz_parse_mime_tlv(curl_mimepart *part, TLV *tlv)
   282  {
   283    int rc;
   284    char *tmp;
   285
   286    switch(tlv->type) {
   287      case TLV_TYPE_MIME_PART_NAME:
   288        tmp = fuzz_tlv_to_string(tlv);
   289        curl_mime_name(part, tmp);
   290        fuzz_free((void **)&tmp);
   291        break;
   292
   293      case TLV_TYPE_MIME_PART_DATA:
   294        curl_mime_data(part, (const char *)tlv->value, tlv->length);
   295        break;
   296
   297      default:
   298        /* The fuzzer generates lots of unknown TLVs - we don't want these in the
   299           corpus so we reject any unknown TLVs. */
   300        rc = 255;
   301        goto EXIT_LABEL;
   302        break;
   303    }
   304
   305    rc = 0;
   306
   307  EXIT_LABEL:
   308
   309    return rc;
   310  }
